import 'reflect-metadata';
import { Module } from '@nestjs/common';
import { CatalogController } from './catalog.controller.mjs';
import { CatalogService } from './catalog.service.mjs';
export class AppModule {}
Module({ controllers: [CatalogController], providers: [CatalogService] })(AppModule);

import 'reflect-metadata';
import assert from 'node:assert/strict';
import test from 'node:test';
import { NestFactory } from '@nestjs/core';
import { AppModule } from '../src/nest/app.module.mjs';
import { CatalogService } from '../src/nest/catalog.service.mjs';

test('Nest serves migrated SQLite data over a real HTTP socket', { timeout: 60000 }, async () => {
  const app = await NestFactory.create(AppModule, { logger: false });
  try {
    const catalog = app.get(CatalogService);
    catalog.migrate();
    catalog.seed([{ id: 'lamp', name: 'Desk Lamp', priceCents: 4950 }, { id: 'desk', name: 'Standing Desk', priceCents: 49900 }]);
    catalog.seed([{ id: 'ignored', name: 'Must Not Duplicate', priceCents: 1 }]);
    await app.listen(0, '127.0.0.1');
    const address = app.getHttpServer().address();
    assert.ok(address && typeof address === 'object');
    const response = await fetch(`http://127.0.0.1:${address.port}/products`);
    assert.equal(response.status, 200);
    assert.deepEqual(await response.json(), {
      products: [
        { id: 'desk', name: 'Standing Desk', priceCents: 49900 },
        { id: 'lamp', name: 'Desk Lamp', priceCents: 4950 }
      ],
      migrations: [1]
    });
  } finally {
    await app.close();
  }
});
